SELECT 
FROM order_form f
JOIN sys_user u ON u.id = f.teacher_id AND u.deleted = 0
LEFT JOIN user_semester_profile p ON p.user_id = f.teacher_id AND p.semester_id = f.semester_id AND p.deleted = 0
LEFT JOIN college c ON c.id = p.college_id AND c.deleted = 0
WHERE f.deleted = 0 AND f.semester_id = #{semesterId}

 AND f.status = #{status}
 AND u.name LIKE CONCAT(#{teacherName}, '%') ESCAPE '|'
ORDER BY f.submitted_at DESC, f.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM order_form f
JOIN sys_user u ON u.id = f.teacher_id AND u.deleted = 0
WHERE f.deleted = 0 AND f.semester_id = #{semesterId}

 AND f.status = #{status}
 AND u.name LIKE CONCAT(#{teacherName}, '%') ESCAPE '|'

SELECT FROM order_form f JOIN sys_user u ON u.id = f.teacher_id AND u.deleted = 0 LEFT JOIN user_semester_profile p ON p.user_id = f.teacher_id AND p.semester_id = f.semester_id AND p.deleted = 0 LEFT JOIN college c ON c.id = p.college_id AND c.deleted = 0 WHERE f.deleted = 0 AND f.semester_id = #{semesterId}
AND EXISTS (SELECT 1 FROM user_semester_profile p3 WHERE p3.user_id = f.teacher_id AND p3.semester_id = f.semester_id AND p3.college_id = #{collegeId} AND p3.deleted = 0)
AND f.status = #{status} AND u.name LIKE CONCAT(#{teacherName}, '%') ESCAPE '|' ORDER BY f.submitted_at DESC, f.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM order_form f JOIN sys_user u ON u.id = f.teacher_id AND u.deleted = 0 WHERE f.deleted = 0 AND f.semester_id = #{semesterId}
AND EXISTS (SELECT 1 FROM user_semester_profile p3 WHERE p3.user_id = f.teacher_id AND p3.semester_id = f.semester_id AND p3.college_id = #{collegeId} AND p3.deleted = 0)
AND f.status = #{status} AND u.name LIKE CONCAT(#{teacherName}, '%') ESCAPE '|'
